#!/usr/bin/env python3
# =====================================================================
#  apply_mutmut.py  —  fence MUTMUT_20261117 (TD-043)
#
#  Mutation testing (mutmut 3) for the safety-critical backend modules, and
#  the tests that the first run showed were missing. Test/tooling only: no
#  app code changes, nothing the app imports at run time.
#
#   scripts/mutation/mutmut_run.py           NEW  weekend runner (Mac): per module, offline,
#                                                 resumable, never the live DB/config; summary table
#   scripts/mutation/mut_shim_suites.py      NEW  runs each repo suite as one pytest test, in a fork
#   scripts/mutation/mut_shim_conftest.py    NEW  blocks every non-loopback socket in mutation runs
#   scripts/mutation/prove_kills.py          NEW  each listed mutant: new suite FAILS on it, PASSES on main
#   scripts/mutation/test_mutmut_run.py      NEW  TC-MUT-0001…0010 (the runner itself)
#   backend/app/execution/test_mutmut_safety.py  NEW  TC-EXEC-0227…0233 (exit driver: the 5
#                                                 most dangerous survivors + siblings)
#                                                 (+ desktop/src-tauri/backend copy if that tree exists)
#   REPO_MAP.md                              regenerated (new suite counted) — .bak-MUTMUT_20261117 first
#
#     cd ~/dev/scalp-app && python3 apply_mutmut.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then (weekend, once online for --setup):
#     python3 scripts/mutation/mutmut_run.py --setup
#     python3 scripts/mutation/mutmut_run.py            # all modules; Ctrl-C and rerun = resume
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "MUTMUT_20261117"
PARENTS = {"backend/app/execution/exit_order_driver.py": ["EXIT_REPEG_FAST_20261116", "WING_FAST_FILL_20261111"],
           "backend/app/execution/broker_truth.py": ["GTT_KILL_LIST_20261115", "BLIND_STOP_20261115",
                                                     "EXIT_ONCE_ALL_20261115"]}
MIRROR = {"backend/app/execution/test_mutmut_safety.py": "desktop/src-tauri/backend/app/execution/test_mutmut_safety.py"}
ITEMS = json.loads(r"""[{"path": "scripts/mutation/mutmut_run.py", "new": "a0b6bb3b7a8c5d4435ddb8e7cb9c7a98f838f2d3f3f02d1a40b162baf61e999d", "blob": ""}, {"path": "scripts/mutation/mut_shim_suites.py", "new": "75917df9a34090fcc9e6a35c87c8434ddbe8f0a5b08b8723a0124429a4b0db70", "blob": ""}, {"path": "scripts/mutation/mut_shim_conftest.py", "new": "961b6b4d4af07fceb87f9f721a63efd5a5a677c38f175f1b3cc46984a9794856", "blob": ""}, {"path": "scripts/mutation/test_mutmut_run.py", "new": "57ca02d142705f2f96a4c97d2e90428d615220ccaca0fcd34b6aa5b8446411c9", "blob": ""}, {"path": "scripts/mutation/prove_kills.py", "new": "bf180790e128a7a5be72940ee30b9fbfe528df520ec9ee4a4ce42bd336fcba89", "blob": ""}, {"path": "backend/app/execution/test_mutmut_safety.py", "new": "950afdc7d2e5b2d7aab392bbc1c6685de6b4e4286ce3ef41fff137a9ab53b74b", "blob": ""}]""")


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


def rd(p):
    if not os.path.exists(p):
        return None
    with open(p, "rb") as f:
        return f.read()


def wr(p, b):
    os.makedirs(os.path.dirname(p) or ".", exist_ok=True)
    t = p + ".tmp-" + FENCE
    with open(t, "wb") as f:
        f.write(b)
    os.replace(t, p)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
MAP = os.path.join(repo, "REPO_MAP.md")
MAP_BAK = MAP + ".bak-" + FENCE
GEN = os.path.join(repo, "scripts", "gen_repo_map.py")


def targets():
    """(repo-relative path, payload key) for every file this script owns, mirrors included."""
    out = [(it["path"], it["path"]) for it in ITEMS]
    for src, dst in MIRROR.items():
        if os.path.isdir(os.path.join(repo, os.path.dirname(dst))):
            out.append((dst, src))
    return out


def regen():
    if not os.path.exists(GEN):
        return True, "no generator"
    r = subprocess.run([sys.executable, GEN], cwd=repo, capture_output=True, text=True)
    return r.returncode == 0, (r.stdout + r.stderr).strip()


def tidy():
    for d in (os.path.join(repo, "scripts", "mutation", "__pycache__"),
              os.path.join(repo, "backend", "app", "execution", "__pycache__")):
        if os.path.isdir(d) and any("mutmut" in n for n in os.listdir(d)):
            for n in os.listdir(d):
                if "mutmut" in n or "prove_kills" in n or "mut_shim" in n:
                    os.remove(os.path.join(d, n))
    d = os.path.join(repo, "scripts", "mutation", "__pycache__")
    if os.path.isdir(d) and not os.listdir(d):
        os.rmdir(d)
    d = os.path.join(repo, "scripts", "mutation")
    if os.path.isdir(d) and not os.listdir(d):
        os.rmdir(d)


def git_dirty(rel):
    try:
        r = subprocess.run(["git", "-C", repo, "status", "--porcelain", "--", rel], capture_output=True,
                           text=True, timeout=30)
        return r.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        return ""


# ── rollback ─────────────────────────────────────────────────────────
if "--rollback" in args:
    rm, later = [], []
    for rel, key in targets():
        p = os.path.join(repo, rel)
        cur = rd(p)
        if cur is None:
            continue
        if sha(cur) == sha(blobs[key]):
            rm.append(p)
        else:
            later.append(rel)
    if later:
        die("cannot roll back — changed after this script: " + ", ".join(later) + ". Undo those edits first.")
    for p in rm:
        os.remove(p)
        say(f"  removed {os.path.relpath(p, repo)}")
    if os.path.exists(GEN):                       # recount from the tree (other changes kept)
        ok, msg = regen()
        say("  REPO_MAP.md regenerated" if ok else f"  !! generator: {msg}")
    elif os.path.exists(MAP_BAK):
        shutil.copy2(MAP_BAK, MAP)
        say("  REPO_MAP.md restored from .bak-" + FENCE)
    if os.path.exists(MAP_BAK):
        os.remove(MAP_BAK)
    tidy()
    say(f"rolled back {len(rm)} file(s). Stage the change: git add -A scripts/mutation backend/app/execution "
        "REPO_MAP.md && git commit")
    sys.exit(0)

# ── 1. state ─────────────────────────────────────────────────────────
plan, done = [], 0
for rel, key in targets():
    cur = rd(os.path.join(repo, rel))
    if cur is None:
        plan.append((rel, key))
    elif sha(cur) == sha(blobs[key]):
        done += 1
    else:
        die(f"{rel} already exists with other content — move it aside and re-run")
if not plan:
    say(f"✓ already applied ({done} file(s) in place) — nothing to do")
    sys.exit(0)
for rel, fences in PARENTS.items():
    cur = rd(os.path.join(repo, rel)) or b""
    miss = [f for f in fences if f.encode() not in cur]
    if miss:
        die(f"{rel} lacks {', '.join(miss)} — pull the latest main first (the tests are written against it)")
if "--allow-dirty" not in args:
    for rel in ["REPO_MAP.md"] + list(PARENTS):
        st = git_dirty(rel)
        if st:
            die(f"git status shows {rel} as '{st[:2].strip()}' — commit or stash it first (or --allow-dirty)")

# ── 2. compile ───────────────────────────────────────────────────────
tmp = tempfile.mkdtemp(prefix="mutmut_apply_")
for rel, key in plan:
    if rel.endswith(".py"):
        f = os.path.join(tmp, os.path.basename(rel))
        with open(f, "wb") as h:
            h.write(blobs[key])
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {rel} does not compile: {e}")
shutil.rmtree(tmp, ignore_errors=True)
say(f"payloads verified and compiled ({len(plan)} file(s))")

# ── 3. write, all or nothing ─────────────────────────────────────────
written = []
old_map = rd(MAP)


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                if os.path.exists(p):
                    os.remove(p)
            else:
                wr(p, old)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")
    if os.path.exists(MAP_BAK) and old_map is not None and rd(MAP) == old_map:
        os.remove(MAP_BAK)
    tidy()


try:
    for rel, key in plan:
        p = os.path.join(repo, rel)
        wr(p, blobs[key])
        written.append((p, None))
        say(f"  wrote {rel}")
    if os.path.exists(GEN) and old_map is not None:
        if not os.path.exists(MAP_BAK):
            shutil.copy2(MAP, MAP_BAK)
        written.append((MAP, old_map))
        ok, msg = regen()
        if not ok:
            raise RuntimeError("generator: " + msg)
        say("  REPO_MAP.md regenerated (backup REPO_MAP.md.bak-" + FENCE + ")")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")

# ── 4. checks ────────────────────────────────────────────────────────
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    env = dict(os.environ, SCALP_TEST_MODE="1", PYTHONPATH=os.path.join(repo, "backend"))
    home = tempfile.mkdtemp(prefix="mutmut_home_")
    env["HOME"] = home                                   # never the real ~/.scalp-app
    py = sys.executable
    for c in (os.path.join(repo, "backend", "venv", "bin", "python"),
              os.path.join(repo, "backend", ".venv", "bin", "python")):
        if os.path.exists(c):
            py = c
            break
    checks = [([py, "backend/app/execution/test_mutmut_safety.py"], "TC-EXEC-0227…0233 on main"),
              ([sys.executable, "scripts/mutation/prove_kills.py"], "every listed mutant killed"),
              ([sys.executable, "scripts/mutation/test_mutmut_run.py"], "TC-MUT-0001…0010")]
    for cmd, what in checks:
        r = subprocess.run(cmd, cwd=repo, env=env, capture_output=True, text=True, timeout=1800)
        outp = (r.stdout or "") + (r.stderr or "")
        if r.returncode != 0:
            restore()
            shutil.rmtree(home, ignore_errors=True)
            die(f"{cmd[-1]} failed — every file restored:\n" + "\n".join(
                "    " + ln for ln in outp.splitlines() if "FAIL" in ln or "MISS" in ln or "Error" in ln)[-3000:])
        say(f"  ✓ {cmd[-1]}: {what} — " + outp.strip().splitlines()[-1])
    shutil.rmtree(home, ignore_errors=True)

tidy()
say(f"\n✓ {FENCE} applied (tests and tooling only — no app code changed, no release needed).")
say("  Commit: git add scripts/mutation backend/app/execution/test_mutmut_safety.py REPO_MAP.md"
    " && git commit -m 'MUTMUT_20261117: mutation testing + exit-driver tests (TD-043)'")
say("  Weekend: python3 scripts/mutation/mutmut_run.py --setup   (once, online)")
say("           python3 scripts/mutation/mutmut_run.py            (all modules; rerun resumes)")
say("  Undo:   python3 apply_mutmut.py --rollback")
